// 步驟：在同一個目標底下用標題找（同標題的步驟可以出現在不同目標）；給 sid 就在整個專案找
function nidRef(v) { v = ph(v); return /^n[0-9a-f]{10}$/.test(v) ? v : ''; }
function legacyRef(v) { v = ph(v); return /^m[0-9]{1,18}$/.test(v) ? v : ''; }
// 歸屬兩端的寫法：節點 id、舊式里程碑別名（m＋舊 id）、票的鍵。格式不對回 ''
function trKind(r) { return nidRef(r) ? 'node' : legacyRef(r) ? 'legacy' : (r ? 'issue' : ''); }
function relList(R, slot) {
