function failedCount(x) {
  var n = 0;
  if (Array.isArray(x)) x.forEach(function (r) { if (r && typeof r === 'object' && r.success === false) n++; });
  return n;
}
// 合併寫入（wbatch）：一個請求回 {ok, results:[{status}]}；FOREACH 每圈的結果可能包了好幾層，往內找
function batchFailed(x) {
  var n = 0;
  if (Array.isArray(x)) x.forEach(function (r) { n += batchFailed(r); });
  else if (x && typeof x === 'object') {
    if (x.success === false) n++;
    else if (Array.isArray(x.results) && x.ok !== undefined) x.results.forEach(function (r) { if (!r || r.status < 200 || r.status >= 300) n++; });
    else if (x.data && typeof x.data === 'object') n += batchFailed(x.data);
    else if (x.body && typeof x.body === 'object') n += batchFailed(x.body);
  }
  return n;
}
// 一批寫入裡「每一筆各自的結果」：往內找（FOREACH 每圈的結果可能包了好幾層），依圈的順序回 [{results:[...]}｜{failedCall:true}]
