  else if (x && typeof x === 'object') {
    if (x.success === false) out.push({ failedCall: true });
    else if (Array.isArray(x.results) && x.ok !== undefined) out.push({ results: x.results });
    else if (x.data && typeof x.data === 'object') batchRuns(x.data, out);
