function parseKey(k) { var m = /^([^#]+)#(\d+)$/.exec(String(k)); return m ? { full: m[1], n: parseInt(m[2], 10) } : null; }

// 1/0 ↔ 布林（slot 裡只有字串）
function actorOf(x) {
  // {{vact.data}} 是引擎回的本體 {valid,…}；保險起見也認多包一層 {data:{valid,…}} 的形狀
  var d = jparse(x);
  if (isObj(d) && d.valid === undefined && d.data !== undefined) d = jparse(d.data);
  if (!isObj(d) || d.valid === undefined) return { valid: false, reason: 'no_answer' };
  return { valid: d.valid === true, login: ph(d.login), role: ph(d.role), reason: ph(d.reason) };
}
function boot(input) {
  var tok = ph(input.token);
  // token 欄放的是引擎簽的「Portal 主人按的」斷言（JSON、有 sig）⇒ 身分看斷言不看 token（0.7.0，inkstone/Arcrun#323）。
  // 斷言由 build.mjs 給 actor:'opt' 的路由排的 vact 站先問引擎驗過，答案在 input.actor；別的路由沒有 vact ⇒ 一律不合格（401）。
  var pj = tok && tok.charAt(0) === '{' ? jparse(tok) : null;
  var isAct = isObj(pj) && typeof pj.sig === 'string' && pj.sig !== '';
  return {
    act: isAct ? actorOf(input.actor) : null,
    q: isObj(jparse(input.query)) ? jparse(input.query) : {},
    body: jparse(input.body),
    params: isObj(jparse(input.params)) ? jparse(input.params) : {},
    tokid: isAct ? 'actor' : (tok ? sha256hex(tok) : 'none'),
    tenant: ph(input.tenant).replace(/[^A-Za-z0-9_-]/g, '_'),     // 引擎注入的 {{_tenant}}；進 record id（id 是跨租戶全域的）
    // 連結的主機（inkstone/Arcrun#326）：引擎注入的「這顆 worker 對外的 origin」優先——那個網址對 leo 的瀏覽器打得開
    // （它會把人帶進 Portal）；呼叫端自報的 base（本機橋是 127.0.0.1）和 ahub.invalid 都是打不開的，只在引擎沒給時才用。
    base: (ph(input.origin) || ph(input.base) || 'https://ahub.invalid').replace(/\/+$/, '')
  };
}
// 分頁（Gitea 的 limit／page；預設 30，上限 100）
function prepOut(B, o) {
  o = o || {};
  var r = { success: true, tokid: B.tokid, base: B.base, tenant: B.tenant, reads: [], early: null, act: B.act || null };
  Object.keys(o).forEach(function (k) { r[k] = o[k]; });
  var list = r.early ? [] : r.reads;
  if (list.length > READS_N) throw new Error('reads ' + list.length + ' 超過這條路由的 ' + READS_N + ' 格');
  r.nreads = list.length;
  // 輸出欄位叫 ahmulti、迭代器也叫 ahmulti：引擎的 FOREACH 在本節點輸出裡找不到清單時，會退而掃整個 context（含呼叫端送來的 body／query）
  // 找同名陣列——名字取得不尋常，呼叫端就沒有機會（不論故意或不小心）用自己的 body 餵出一串要執行的讀寫。
  delete r.reads;
  if (!PUBLIC && B.tokid === 'none') { r.whon = 0; r.nreads = 0; r.ahmulti = []; return r; }     // 沒帶 token：什麼都不讀
  if (!PUBLIC && r.act && !actOk(r.act)) { r.whon = 0; r.nreads = 0; r.ahmulti = []; return r; }   // 斷言不合格：什麼都不讀，decide 回 401／403
  // 身分那一讀：token ⇒ ahub_token；斷言 ⇒ 租戶設定（主人在這個租戶的署名，inkstone/Arcrun#328）
  r.whon = PUBLIC ? 0 : 1;
  var all = (r.whon ? [r.act ? rdSetting() : rd(T.token, 'token_sha256', B.tokid, 5)] : []).concat(list);
  r.ahmulti = all.length ? [{ reads: all }] : [];   // 一個請求做完這一批（inkstone/Arcrun#446）；沒有要讀的＝FOREACH 不跑
  return r;
}
function prepEarly(B, status, msg) { return prepOut(B, { early: { status: status, body: { message: msg, url: '' } } }); }
// 第二段讀（prep2）：第一段讀完才知道要讀什麼的時候用。兩種：
//   list（路由標頭的 reads2）：prep2 回 ahsmulti（要讀的 by-template 清單，包成一個請求），引擎並行讀完，結果在 input.reads2（陣列）
//   batch（路由標頭的 batch2）：prep2 回 ids（要讀的 record id），一個請求讀完（inkstone/Arcrun#307 的 batch-get），結果在 input.reads2（一個物件）
function readsBad(arr) {
  for (var i = 0; i < arr.length; i++) if (isObj(arr[i]) && arr[i].success === false) return arr[i];
  return null;
}
function actOk(A) { return !!(A && A.valid === true && A.role === 'admin'); }
// 租戶設定（ahub_setting，key=signoff；inkstone/Arcrun#328）。沒設＝{owner_name:'', approvers:[]}
function rdSetting() { return rd(T.setting, 'key', 'signoff', 5); }
// 全部設定列（含「某版本已被簽核人同意」的紀錄 key=approved:<版本>；inkstone/Arcrun#387）
function bodyObj(B) { return isObj(B.body) ? B.body : {}; }
var REPO_SCAN = 500;

// ── 搶號（inkstone/Arcrun#307 的 create_only）──────────────────────────────────────────────────────────────
// 票號要「只有一個請求拿得到」：票的 record id 由租戶＋票的鍵決定（issueRid），建的時候帶 create_only——
// KBDB 的主鍵讓第二個建同一個 id 的請求拿到 409（不是靜默成功），於是它改搶下一號（build.mjs 把 CLAIM_TRIES 個嘗試排成一串，ON_FAIL 接下一個）。
// 🔴 id 是全域的（跨租戶共用一張表），所以一定要帶租戶；id 會進 PATCH 的網址，所以只用網址安全的字元（~ 不會出現在 owner／repo 名字裡）。
var CLAIM_TRIES = 8;
function issueRid(tenant, key) {
  var p = parseKey(key);
  if (!p || !tenant) throw new Error('issueRid 需要 tenant 與合法的票鍵');
  return 'ahub~' + tenant + '~i~' + p.full.replace('/', '~') + '~' + p.n;
}

var READS_N = 3;
var PUBLIC = false;

var B = boot(input);
var full = fullOf(B.params), id = intOf(B.params.id, 0), b = bodyObj(B), name = ph(b.name);
if (!full || !id) return prepEarly(B, 404, 'release not found');
if (!name) return prepEarly(B, 422, 'name is required');
return prepOut(B, { full: full, id: id, asset: b, reads: [rd(T.repo, 'full_name', full, 5), rd(T.rel, 'repo', full, REPO_SCAN), rd(T.att, 'repo', full, REPO_SCAN)] });

function ph(v) { v = String(v == null ? '' : v).trim(); return /^\{\{[^{}]*\}\}$/.test(v) ? '' : v; }
function jparse(v) {
  if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } }
  return v === undefined ? null : v;
}
function isObj(v) { return v !== null && typeof v === 'object' && !Array.isArray(v); }
// 一批讀是「一個請求回一串」（inkstone/Arcrun#446）：FOREACH 只有一圈，results 是 [{success,status,data:{results:[每個讀的回應]}}]。
// 這裡攤平回「每個讀一格」的陣列，下游的 readsBad／rowsOf／allRows 一字不改。不是這個形狀（例如沒有要讀的 []）就原樣回。
function flatMulti(x) {
