  var m = x[0], d = m && typeof m === 'object' ? jparse(m.data) : null;
  return d && Array.isArray(d.results) ? d.results : x;
}
function nowIso() { return new Date().toISOString().replace(/\.\d+Z$/, 'Z'); }
function newNumId() { return Date.now() * 1000 + Math.floor(Math.random() * 1000); }
function reply(status, body) { return { success: true, status: status, body: body }; }
function fail(status, message) { return reply(status, { message: message, url: '' }); }

// ── 邊界驗證 ───────────────────────────────────────────────────────────────
var T = {
  repo: 'ahub_repo', issue: 'ahub_issue', comment: 'ahub_comment', label: 'ahub_label', ms: 'ahub_milestone',
  ilabel: 'ahub_issue_label', iassign: 'ahub_issue_assignee', dep: 'ahub_dependency', user: 'ahub_user', token: 'ahub_token',
  rel: 'ahub_release', att: 'ahub_attachment',
  rlink: 'ahub_release_link', cmeta: 'ahub_comment_meta', setting: 'ahub_setting',
  station: 'ahub_station', claim: 'ahub_claim', ask: 'ahub_report_ask',
  session: 'ahub_session',
  goal: 'ahub_goal', glog: 'ahub_goal_log', step: 'ahub_step', sassign: 'ahub_step_assign', gms: 'ahub_goal_ms', stage: 'ahub_stage', ssay: 'ahub_step_say',
  node: 'ahub_node', member: 'ahub_member', gref: 'ahub_goal_ref', evt: 'ahub_issue_event',
  gitw: 'ahub_git_write',
  tmeta: 'ahub_tmeta', roster: 'ahub_roster', tref: 'ahub_tref', tlog: 'ahub_tlog', visa: 'ahub_visa'
};

// ── 讀：GET /kbdb/records/by-template/<template>?field=&value=&limit=&offset=（租戶由代轉層注入）──────────────
// field／value 是「某一格等於某個值」的精確比對（伺服器端走索引，成本只跟命中筆數成正比）；一次只能比一格。
// 新→舊排序；單頁上限 500。
function innerOf(r) {
  if (!r) return null;
  if (Array.isArray(r.records) || r.record) return r;       // 已經是 KBDB 的本體
  if (r.success === false) return null;
  return jparse(r.data);                                    // recipe 的外殼 {success, status, data}
}
function rowsOf(r) {
  var d = innerOf(r);
  if (!d) return [];
  var a = Array.isArray(d.records) ? d.records : (d.record ? [d.record] : []);
  return a.map(function (x) { return { rid: x.record_id, v: isObj(x.values) ? x.values : {} }; });
}
// 讀滿一整頁＝可能還有更多（KBDB 的 total 在頁滿時只給下界）——呼叫端據此決定要不要說「這裡只看了最近 N 筆」
