function allRows(results, from, to) {
  var out = [];
  for (var i = from || 0; i < (to === undefined ? results.length : to); i++) rowsOf(results[i]).forEach(function (x) { out.push(x); });
  return out;
}

// ── 寫：POST /kbdb/records（建一筆）、PATCH /kbdb/records/<rid>（改幾格）──────────────────────────────────
// 值一律是字串；空的格子不寫（讀回來就是 ''），省寫入——一格約占兩列、約 0.5～1 秒。
function compact(v) {
  var o = {};
  Object.keys(v).forEach(function (k) { var x = v[k]; if (x !== undefined && x !== null && String(x) !== '') o[k] = String(x); });
  return o;
}
function postRec(tpl, v) { return { template: tpl, values: compact(v) }; }
// 改幾格：只送真的變了的格子；把一個本來就是空的格子「改成空」是沒事做，不送
function patchRec(R, v) {
  var o = {}, n = 0;
  Object.keys(v).forEach(function (k) {
    var x = v[k] === undefined || v[k] === null ? '' : String(v[k]);
    if (x === sv(R, k)) return;
    o[k] = x; n++;
  });
  return n ? { id: R.rid, values: o } : null;
}
function isOn(R, k) { return sv(R, k) === '1'; }

// ── 文件：從 record 解出來的欄位 ────────────────────────────────────────────
function meOf(who, tokid) {
  if (!tokid || tokid === 'none') return '';
  var rows = rowsOf(who);
  for (var i = 0; i < rows.length; i++) {
    if (sv(rows[i], 'token_sha256') === tokid && !isOn(rows[i], 'revoked')) return sv(rows[i], 'login');
  }
  return '';
}
// prep 共用的起手式：解析請求信封。路徑參數由橋依路由表切好放在 params。
function oldestBy(rows, pred) {
  var hit = null;
  rows.forEach(function (R) { if (pred(R)) hit = R; });      // 讀回是新→舊，最後一個符合的就是最舊的
  return hit;
}
function repoRowOf(result, full) { return oldestBy(rowsOf(result), function (R) { return sv(R, 'full_name') === full; }); }
function attDoc(R) {
  return { rid: R.rid, aid: sv(R, 'aid'), repo: sv(R, 'repo'), kind: sv(R, 'parent_kind'), parent: sv(R, 'parent'), name: sv(R, 'name'),
    size: parseInt(sv(R, 'size') || '0', 10) || 0, created_at: sv(R, 'created_at'), source: sv(R, 'source'), r2_key: sv(R, 'r2_key'), sha256: sv(R, 'sha256') };
}
function assetView(A) {
  var n = parseInt(A.aid, 10);
  return { id: n > 0 ? n : 0, uuid: A.aid, name: A.name, size: A.size, download_count: 0, created_at: A.created_at,
    browser_download_url: A.source || '', r2_key: A.r2_key || '', sha256: A.sha256 || '' };
}
function attsFromBody(list, full, gid, now) {
  var out = [];
  (Array.isArray(list) ? list : []).slice(0, 50).forEach(function (a) {
    if (!isObj(a)) return;
    var name = ph(a.name); if (!name) return;
    var size = parseInt(ph(a.size), 10);
    out.push(postRec(T.att, { aid: String(newNumId() + out.length), repo: full, parent_kind: 'release', parent: String(gid), name: name,
      size: size > 0 ? size : '', created_at: now, source: ph(a.url) || ph(a.browser_download_url) || ph(a.source), r2_key: ph(a.r2_key), sha256: ph(a.sha256).toLowerCase() }));
  });
  return out;
}

// ── 里程碑總覽（跨 repo；0.6.0）──────────────────────────────────────────────────────────────────────
// 挑出這一頁要列的里程碑：state（open／closed／all）、repo 篩選、排序（開著的按期限近→遠、沒期限的最後；已關的按關閉時間新→舊）、分頁。
// prep2（決定要讀哪幾個里程碑的票）與 decide（接結果）必須挑出同一批同一個順序，所以共用這一支。
function readsBad(arr) {
  for (var i = 0; i < arr.length; i++) if (isObj(arr[i]) && arr[i].success === false) return arr[i];
  return null;
}
function meIn(input) {
  var P = input.prep, a = Array.isArray(input.reads) ? input.reads : [];
  if (P && P.act) return actOk(P.act) && P.whon ? ownerNameOf(settingsOf(a[0]), P.act) : '';
  return P && P.whon ? meOf(a[0], P.tokid) : '';
}
// 斷言驗過、而且是 Portal 的管理員（實例主人）才算；作者名由 ownerNameOf 決定
function actOk(A) { return !!(A && A.valid === true && A.role === 'admin'); }
// 租戶設定（ahub_setting，key=signoff；inkstone/Arcrun#328）。沒設＝{owner_name:'', approvers:[]}
function settingsOf(r) {
  var R = null;
  rowsOf(r).forEach(function (x) { if (!R && sv(x, 'key') === 'signoff') R = x; });     // 新→舊，取最新一筆
  return { R: R, owner_name: sv(R, 'owner_name'), approvers: approverList(sv(R, 'approvers')) };
}
// 實例主人從 Portal 寫入時的署名：租戶設定的 owner_name；沒設就用 Portal 的登入名（不再寫死 Leo）
function ownerNameOf(S, A) { return (S && S.owner_name) || (A && A.login) || ''; }
// 斷言不合格時回什麼：驗不過 401、不是主人 403（先驗身分——沒通過的人不該從錯誤訊息得知東西存不存在）
function actFail(A) {
  if (!A || A.valid !== true) return fail(401, 'portal actor is not valid' + (A && A.reason ? ' (' + A.reason + ')' : ''));
  return fail(403, 'only the instance owner (portal admin) can write from the Portal');
}
// 讀取型路由 decide 的起手式：驗身分、驗讀有沒有失敗、驗 prep 有沒有早退。回 { stop: <回應> } 或 { P, me }
function gate(input) {
  var P = input.prep, a = Array.isArray(input.reads) ? input.reads : [];
  if (P.act && !actOk(P.act)) return { stop: actFail(P.act) };
  if (!P.whon && !P.act) return { stop: fail(401, 'token is required') };      // 沒帶 token（prep 什麼都沒讀）
  var bad = readsBad(a);
  if (bad) return { stop: fail(502, 'KBDB read failed (HTTP ' + (bad.status || '?') + ')') };
  var me = meIn(input);
