    .concat(pt.map(function (p) { return { op: 'patch', id: p.id, values: p.values }; }))
    .concat(rl.map(function (r) { return { op: 'relation', id: r.id, slot: r.slot, add: r.add, remove: r.remove }; }));
  // 代轉層一次最多 20 筆（inkstone/Arcrun#325）；多的分批，批與批依序（FOREACH concurrency 1），每批內並行
  var batches = [];
  for (var i = 0; i < ops.length; i += 20) batches.push({ ops: ops.slice(i, i + 20) });
