}
// 關聯格的一筆寫入（inkstone/Arcrun#368，建在 KBDB 關聯格 #370 上）：往記錄 id 的 slot 加／移外鍵
function gateW(input) {
  var g = gate(input);
  if (g.stop) return { stop: done(g.stop) };
  return g;
}
// reads 結果：把身分那一讀拿掉，剩下的就是路由自己排的讀取（下標 0＝prep 排的第一個）
function readsOf(input) { var a = Array.isArray(input.reads) ? input.reads : []; return a.slice(input.prep && input.prep.whon ? input.prep.whon : 0); }
function notFound(what) { return fail(404, what + ' not found'); }
// 「這個 repo 的票／標籤／里程碑」一次最多看多少筆（KBDB 單頁上限 500）。讀滿了就是可能被截斷，見 README「已知上限」
function approverList(v) {
  var a = Array.isArray(v) ? v : String(v == null ? '' : v).split(',');
  var seen = {}, out = [];
  a.forEach(function (x) { x = String(x == null ? '' : x).trim(); var k = x.toLowerCase(); if (x && !seen[k]) { seen[k] = 1; out.push(x); } });
  return out;
}

input.reads = flatMulti(input.reads);

var g = gateW(input); if (g.stop) return g.stop;
var P = g.P, rs = readsOf(input);
if (!repoRowOf(rs[0], P.full)) return done(notFound('repository'));
var R = oldestBy(rowsOf(rs[1]), function (x) { return sv(x, 'gid') === String(P.id); });
if (!R) return done(notFound('release'));
var atts = attsFromBody([P.asset], P.full, P.id, nowIso());
var same = rowsOf(rs[2]).map(attDoc).filter(function (A) { return A.kind === 'release' && A.parent === String(P.id); });
if (same.some(function (A) { return A.name === atts[0].values.name; })) return done(fail(409, 'asset with this name already exists on the release'));
return done(reply(201, assetView(attDoc({ rid: '', v: atts[0].values }))), atts, [patchRec(R, { assets: same.length + 1 })]);

function reply(status, body) { return { success: true, status: status, body: body }; }
function fail(status, message) { return reply(status, { message: message, url: '' }); }

// ── 邊界驗證 ───────────────────────────────────────────────────────────────

function failedCount(x) {
  var n = 0;
